import json
import requests

from taf.ul.kpi_selector.utilities.exceptions import WFTError


class BuildEndpoint(object):
    """ Class representation of build endpoint of WFT Web API. """

    def __init__(self, project, component, version):
        self.config = ModelConfig()
        self._url = "{}/{}/{}/builds/{}.json".format(
            self.config.wft_api_address, project, component, version
        )
        self._version = version

    def sub_builds(self):
        """
        Gets sub builds from WFT Web API

        :return: list of sub builds with details
            E.g. output::
            [{
              "id": 4342267,
              "sc": "NIDD_EQM",
              "title": "NIDD_EQM",
              "component": "NIDD_EQM",
              "project": "Common",
              "version": "EQM20B_2010_001_00"
            },
            {
              "id": 4342270,
              "sc": "NIDD_EQM_R",
              "title": "NIDD_EQM_R",
              "component": "NIDD_EQM_R",
              "project": "Common",
              "version": "EQMR20B_2010_001_00"
            }]
        :rtype: list of dicts
        """
        self._url = "{}?items[]=sub_builds&access_key={}".format(
            self._url, self.config.access_key
        )
        return json.loads(self._request(params="sub_builds"))["sub_builds"]

    def build_attributes(self):
        """
        Gets build attributes from WFT Web API

        :return: dict of build attributes
        :rtype: dict
        """
        self._url = "{}?items[]=sub_builds&access_key={}".format(
            self._url, self.config.access_key
        )
        return json.loads(self._request(params="build_attributes"))

    def get_rfsw_build_project(self, rfsw):
        """
        Gets project info of RF software build, e.g. {
            "project": "Common",
            "component": "RF-Module_5",
            "version": "RF.FRM5.24R2.20241007.001"
        }
        :param rfsw: RF software build
        :type rfsw: str
        :return: project info of RF software build
        :rtype: dict
        """
        self._url = "{}build.json?access_key={}&" \
                    "view[items]=20&view[sorting_field]=created_at&view[sorting_direction]=DESC&" \
                    "view[columns][][id]=deliverer.project.full_path&view[columns][][id]=deliverer.title&" \
                    "view[columns][][id]=version&view[columns][][id]=branch.title&view[columns][][id]=state&" \
                    "view[columns][][id]=planned_delivery_date&view[columns][][id]=common_links&" \
                    "view[columns][][id]=compare_link&view[view_filters_attributes][810550989717395][column]=version&" \
                    "view[view_filters_attributes][810550989717395][operation]=eq&" \
                    "view[view_filters_attributes][810550989717395][value][]={}".\
            format(self.config.wft_api_address, self.config.access_key, rfsw)

        try:
            rfsw_info = json.loads(self._request(params="get_rfsw_build_project"))["items"][0]
        except IndexError:
            raise WFTError("RF software build with version: {} does not exist.".format(rfsw))

        rfsw_project_info = {
            "project": rfsw_info["deliverer.project.full_path"],
            "component": rfsw_info["deliverer.title"],
            "version": rfsw_info["version"]
        }

        return rfsw_project_info

    def get_baseline_sw_build(self):
        """
        Gets baseline SW build, using the knifeID to filter the knife table and match it with correct SW build
        :return: baseline SW build
        :rtype: str
        """
        knife_id = self._version.split("_")[-1]
        self._url = "{}knife_request.json?access_key={}&view[items]=20&view[sorting_field]=id&" \
                    "view[sorting_direction]=DESC&view[columns[][id]]=id&view[columns[][id]]=baseline&" \
                    "view[view_filters_attributes[404173755806238]][column]=id&" \
                    "view[view_filters_attributes[404173755806238]][operation]=eq&" \
                    "view[view_filters_attributes[404173755806238]][value][]={}".\
            format(self.config.wft_api_address, self.config.access_key, knife_id)

        return json.loads(self._request(params="get_baseline_sw_build"))["items"][0]["baseline"]

    @staticmethod
    def _check_response(response):
        if not response.ok:
            msg = (
                "endpoint returned bad response: "
                '"({response.status_code}) {response.reason}".'
            )
            msg = msg.format(response=response)
            raise WFTError(msg)

    def _request(self, params):
        response = requests.get(self._url, params=params, timeout=60)
        self._check_response(response)
        return response.content


